systems as plain functions executed in registered order."""


class World:
    def __init__(self):
        self._next_id = 0
        self._components = {}          # component_type -> {entity_id: data}
        self._alive = set()
        self._destroy_queue = []       # deferred destroyals, flushed at end of frame

    # -- entities -----------------------------------------------------------

    def create(self):
        eid = self._next_id
        self._next_id += 1
        self._alive.add(eid)
        return eid

    def destroy(self, eid):
        """Queue destruction; takes effect at end of frame (flush)."""
        if eid in self._alive:
            self._destroy_queue.append(eid)

    def is_alive(self, eid):
        return eid in self._alive

    def flush(self):
        """End-of-frame: actually remove queued entities."""
        while self._destroy_queue:
            eid = self._destroy_queue.pop()
            self._alive.discard(eid)
            for store in self._components.values():
                store.pop(eid, None)

    # -- components ---------------------------------------------------------

    def add(self, eid, ctype, data):
        self._components.setdefault(ctype, {})[eid] = data

    def get(self, eid, ctype):
        return self._components.get(ctype, {}).get(eid)

    def remove(self, eid, ctype):
        self._components.get(ctype, {}).pop(eid, None)

    # -- queries -------------------------------------------------------------

    def query(self, *ctypes):
        """Yield exactly the entities holding ALL requested components."""
        if not ctypes:
            return iter(())
        stores = [self._components.get(ct) for ct in ctypes]
        if any(s is None for s in stores):
            return iter(())
        smallest = min(stores, key=len)
        for eid in list(smallest.keys()):
            if eid in self._alive and all(eid in s for s in stores):
                yield eid


