def MovementSystem(world, dt):
    for eid in world.query(Position, Velocity):
        pos = world.get(eid, Position)
        vel = world.get(eid, Velocity)
        pos["x"] += vel["vx"] * dt
        pos["y"] += vel["vy"] * dt


